var st = TutorialManager.current_lesson.steps[TutorialManager.current_step_index]
var body = TutorialScript.render_text(TutorialScript.body_for_device(st, false), false)
return TutorialManager.current_step_id() == 'camera' and body.contains("two fingers")

var c0 = Vector2(900,600)
var c1 = Vector2(1000,600)
var d0 = Vector2(0,-120)
var d1 = Vector2(0,-120)
for k in range(1, 9):
	TouchInputAdapter.inject_drag(0, c0 + d0 * k / 8.0)
	TouchInputAdapter.inject_drag(1, c1 + d1 * k / 8.0)
TouchInputAdapter.inject_touch(0, c0 + d0, false)
TouchInputAdapter.inject_touch(1, c1 + d1, false)
return true

