var p = TouchInputAdapter.get_meta('g')
for k in range(1, 13):
	TouchInputAdapter.inject_drag(0, p + Vector2(0, 5 * k))
return true

var o = tree.root.get_node_or_null('TutorialOverlay')
for r in o.find_children('*', 'RichTextLabel', true, false):
	if r.is_visible_in_tree() and r.text.contains('[?]') and r.text.contains('toolbar'):
